def difference_paths(expected,actual,path='schema'):
    if type(expected) is not type(actual):return [path+'.type']
    if isinstance(expected,dict):
        out=[] if set(expected)==set(actual) else [path+'.keys']
        for key in expected:
            if key in actual:out.extend(difference_paths(expected[key],actual[key],path+'.'+key))
        return out[:100]
    if isinstance(expected,list):
        out=[] if len(expected)==len(actual) else [path+'.length']
        for index,(left,right) in enumerate(zip(expected,actual)):out.extend(difference_paths(left,right,path+'['+str(index)+']'))
        return out[:100]
    return [] if expected==actual else [path]

